'use client';

import * as React from 'react';
import {
  Box,
  Button,
  Chip,
  DataGrid,
  Divider,
  Drawer,
  Filter,
  IconButton,
  Navbar,
  NeofloLogo,
  Stack,
  TextField,
  ToggleButton,
  Tooltip,
  Typography,
  countActiveFilters,
} from '@neofloai/atoms';
import {
  ChartLineIcon,
  FadersHorizontalIcon,
  MagnifyingGlassIcon,
  QuestionIcon,
  SidebarSimpleIcon,
  SquaresFourIcon,
} from '@neofloai/atoms/icons';

import type { FilterValue } from '@neofloai/atoms';
import { QUERY_COLUMNS, QUERY_ROWS, filterQueries } from './queries';
import { FILTER_GROUPS } from './facets';

/**
 * The folded rail. A width the rail is in, not a rung on the scale —
 * which is why it goes to size as a number and animates on its own.
 */
const RAIL_COLLAPSED_PX = 64;

/** Gutter the rail's blocks stretch between. Expanded only. */
const RAIL_GUTTER_PX = 16;

const NAV = [
  { key: 'queries', label: 'Query log', Icon: SquaresFourIcon },
  { key: 'analytics', label: 'Analytics', Icon: ChartLineIcon },
];

const FOOTER_NAV = [{ key: 'help', label: 'Help', Icon: QuestionIcon }];

/**
 * One nav row. A pill the width of the block expanded, a square the
 * height of the row collapsed: the fill is the part of a row the eye
 * reads, and a wide one beside a column of icons reads as a rectangle.
 */
function NavRow({ item, collapsed, selected, onSelect }) {
  const { label, Icon } = item;
  return (
    <Tooltip title={collapsed ? label : ''} placement="right">
      <ToggleButton
        value={label}
        selected={selected}
        onChange={onSelect}
        appearance="text"
        size="md"
        sx={{
          height: 28,
          minHeight: 28,
          gap: 1,
          width: collapsed ? 28 : '100%',
          alignSelf: collapsed ? 'center' : 'stretch',
          justifyContent: collapsed ? 'center' : 'flex-start',
          px: collapsed ? 0 : 1,
          textTransform: 'none',
          // The panel is mid-animation while this row is still laid out at
          // its old width. Pinning the glyph and refusing the wrap leaves
          // the label to be clipped by the panel, which is what should
          // absorb it.
          whiteSpace: 'nowrap',
          '& svg': { flexShrink: 0 },
        }}
      >
        <Icon size={20} />
        {!collapsed && label}
      </ToggleButton>
    </Tooltip>
  );
}

/**
 * The rail: brand, the nav it takes you around by, and a footer group
 * pinned to the bottom. Four blocks separated by space rather than rules.
 */
function NavRail({ collapsed, active, onNavigate }) {
  const block = {
    px: collapsed ? 0 : RAIL_GUTTER_PX + 'px',
    alignItems: collapsed ? 'center' : 'stretch',
  };

  return (
    <Drawer
      variant="permanent"
      size={collapsed ? RAIL_COLLAPSED_PX : 'sm'}
      slotProps={{ paper: { sx: { position: 'relative', py: 2.5 } } }}
    >
      <Stack sx={{ ...block, pb: 2, flexShrink: 0 }}>
        <Box sx={{ display: 'flex', color: 'text.primary' }}>
          <NeofloLogo variant={collapsed ? 'mark' : 'full'} size={16} />
        </Box>
      </Stack>

      {/* Takes the slack, which is what pins the footer group down. */}
      <Stack sx={{ ...block, flex: 1, minHeight: 0, gap: 1 }}>
        {NAV.map((item) => (
          <NavRow
            key={item.key}
            item={item}
            collapsed={collapsed}
            selected={active === item.key}
            onSelect={() => onNavigate(item.key)}
          />
        ))}
      </Stack>

      <Stack sx={{ ...block, gap: 1, flexShrink: 0 }}>
        {FOOTER_NAV.map((item) => (
          <NavRow
            key={item.key}
            item={item}
            collapsed={collapsed}
            selected={active === item.key}
            onSelect={() => onNavigate(item.key)}
          />
        ))}
      </Stack>
    </Drawer>
  );
}

export default function QueryLogPage() {
  const [collapsed, setCollapsed] = React.useState(true);
  const [active, setActive] = React.useState('queries');

  const [selection, setSelection] = React.useState<FilterValue>({});
  const [search, setSearch] = React.useState('');
  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

  const activeCount = countActiveFilters(FILTER_GROUPS, selection);
  const isFiltered = activeCount > 0 || search.trim() !== '';
  const rows = filterQueries(QUERY_ROWS, search, selection);

  function clearFilters() {
    setSelection({});
    setSearch('');
  }

  /* The rail runs the full height and the bar starts where it ends, so
     the outer box is a row: rail, then a column. */
  return (
    <Stack direction="row" sx={{ height: '100vh' }}>
      <NavRail collapsed={collapsed} active={active} onNavigate={setActive} />

      <Stack sx={{ flex: 1, minWidth: 0 }}>
        {/* The bar holds the one control whose position does not move when
            the rail folds. Per-page actions go in the space after it. */}
        <Navbar>
          <IconButton
            variant="secondary"
            appearance="text"
            size="sm"
            aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            onClick={() => setCollapsed((previous) => !previous)}
          >
            <SidebarSimpleIcon />
          </IconButton>
        </Navbar>

        {/* Bands: title, toolbar, grid. The first two are as tall as what
            is in them and the grid takes everything left, so the footer
            lands on the bottom edge of the screen at any height. */}
        <Stack sx={{ flex: 1, minHeight: 0 }}>
          <Box sx={{ px: 3, py: 3 }}>
            <Typography variant="h3" component="h1">
              Query Log
            </Typography>
          </Box>
          <Divider />

          <Stack
            direction="row"
            sx={{
              px: 3,
              py: 2,
              gap: 1.5,
              alignItems: 'center',
              justifyContent: 'space-between',
            }}
          >
            <TextField
              placeholder="Search..."
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              startAdornment={<MagnifyingGlassIcon />}
              sx={{ width: 280 }}
            />
            <Stack direction="row" sx={{ gap: 1 }}>
              <Button
                variant="secondary"
                appearance="outline"
                disabled={!isFiltered}
                onClick={clearFilters}
              >
                Clear Filters
              </Button>
              <Button
                variant="secondary"
                appearance="outline"
                startIcon={<FadersHorizontalIcon />}
                onClick={(event) => setAnchorEl(event.currentTarget)}
              >
                Filter
                {activeCount > 0 && (
                  <Chip
                    size="sm"
                    variant="primary"
                    component="span"
                    label={activeCount}
                  />
                )}
              </Button>
            </Stack>
          </Stack>
          <Divider />

          {/* A definite height for the grid to be 100% of. Without the
              minHeight the rows would push the column taller than the
              screen instead of scrolling inside it. */}
          <Box sx={{ flex: 1, minHeight: 0 }}>
            <DataGrid
              size="sm"
              rows={rows}
              columns={QUERY_COLUMNS}
              rowNoun="queries"
              pageSizeOptions={[10, 25, 50]}
              initialState={{
                pagination: { paginationModel: { pageSize: 10 } },
              }}
            />
          </Box>
        </Stack>
      </Stack>

      {/* The trigger sits at the right end of the toolbar, so the panel
          hangs off its right edge — left-aligned it would run off the
          page and be pushed back in, lining up with nothing. */}
      <Filter
        groups={FILTER_GROUPS}
        value={selection}
        onChange={setSelection}
        anchorEl={anchorEl}
        open={anchorEl !== null}
        onClose={() => setAnchorEl(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      />
    </Stack>
  );
}

'use client';

import * as React from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  DataGrid,
  Divider,
  Grid,
  IconButton,
  Menu,
  MenuItem,
  NAVBAR_META_ICON_PX,
  Navbar,
  NavbarTitle,
  Select,
  Stack,
  TextField,
  Tooltip,
  Typography,
} from '@neofloai/atoms';
import {
  ArrowRightIcon,
  BuildingsIcon,
  CalendarBlankIcon,
  CaretDownIcon,
  FilePdfIcon,
  ListIcon,
  ScissorsIcon,
  TicketIcon,
  UploadSimpleIcon,
  WrenchIcon,
} from '@neofloai/atoms/icons';
import { fontFamilies, spacing, text } from '@neofloai/atoms/tokens';

import type { GridColDef } from '@neofloai/atoms';

// The rail, the record and the tax codes are the application's. The rail is
// the same workflow strip the extraction and matching screens mount, so it is
// imported rather than redrawn — a second copy would drift from the screens
// either side of this one.
import {
  AppRail,
  WORKFLOW_NAV,
  WORKFLOW_SECONDARY_NAV,
} from './AppRail';
import {
  HEADER_FIELDS,
  HEADER_META,
  LINE_ITEMS,
  VAT_CODES,
  WHT_CODES,
  formatMoney,
  formatVariance,
  isBlocked,
  money,
  simulate,
  variance,
} from './postingRecord';

import type { Finding, LineItem, TaxCode } from './postingRecord';

/** Gap between the trailing actions, as the frame draws it (Scale/250). */
const ACTION_GAP = 1.5;

/** Lines a page holds, and the choices the footer offers. */
const PAGE_SIZE = 10;
const PAGE_SIZE_OPTIONS = [10, 25, 50];

/** How long the two round trips take. Your API decides this, not the screen. */
const SIMULATE_MS = 700;
const POST_MS = 900;

/* ---------------------------------------------------------------- cells */

/**
 * The line number. Mono, and quieter than the description beside it: it is
 * the line's position rather than one of its fields, and it exists so that a
 * finding can say "line 3" and be followed.
 */
function IndexCell({ value }: { value: number }) {
  return (
    <Box
      component="span"
      sx={(theme) => ({
        fontFamily: fontFamilies.product.mono,
        fontSize: 12,
        color: text.default.placeholder.light,
        ...theme.applyStyles('dark', { color: text.default.placeholder.dark }),
      })}
    >
      {value}
    </Box>
  );
}

/**
 * A money cell: currency mark in caption ink, digits in mono, both pushed
 * right so the decimal points line up down the column. Lined-up decimals are
 * the only reason a reader can compare two figures without reading either.
 */
function AmountCell({ value }: { value: number }) {
  return (
    <Box
      component="span"
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'flex-end',
        gap: '2px',
        width: '100%',
        lineHeight: 'normal',
      }}
    >
      <Box
        component="span"
        sx={(theme) => ({
          color: text.default.placeholder.light,
          ...theme.applyStyles('dark', {
            color: text.default.placeholder.dark,
          }),
        })}
      >
        $
      </Box>
      <Box component="span" sx={{ fontFamily: fontFamilies.product.mono }}>
        {value.toLocaleString('en-US', {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        })}
      </Box>
    </Box>
  );
}

/**
 * A tax column's header: the label, its required mark, and a caret that sets
 * the code on every line at once.
 *
 * The mark is a plain asterisk. TextField draws its own in the label's ink,
 * and the frame draws both in text/error/4 — but recolouring it here would
 * make this screen's required fields look different from every other
 * screen's. The header matches what TextField does; closing the gap with the
 * frame is TextField's job, not this screen's.
 *
 * The frame draws a caret on these two headers and on none of the others,
 * which is what identifies it as a bulk control rather than a sort menu —
 * Description and Line Total are the sortable columns and they carry none. It
 * earns its place on a ten-line invoice, where every line usually takes the
 * same code and setting it row by row is ten decisions made the same way.
 */
function TaxHeader({
  label,
  options,
  onApplyAll,
}: {
  label: string;
  options: readonly TaxCode[];
  onApplyAll: (value: string) => void;
}) {
  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

  return (
    <Box
      component="span"
      sx={{ display: 'flex', alignItems: 'center', gap: '2px', minWidth: 0 }}
    >
      {label}*
      <Tooltip title={'Set ' + label + ' on every line'}>
        <IconButton
          variant="secondary"
          appearance="text"
          size="sm"
          aria-label={'Set ' + label + ' on every line'}
          onClick={(event) => setAnchorEl(event.currentTarget)}
        >
          <CaretDownIcon size={14} />
        </IconButton>
      </Tooltip>
      <Menu
        anchorEl={anchorEl}
        open={anchorEl !== null}
        onClose={() => setAnchorEl(null)}
      >
        {options.map((option) => (
          <MenuItem
            key={option.value}
            onClick={() => {
              onApplyAll(option.value);
              setAnchorEl(null);
            }}
          >
            {option.label}
          </MenuItem>
        ))}
      </Menu>
    </Box>
  );
}

/**
 * The one control on a line, and it changes with what the check found.
 *
 * Split is always available: a line covering two cost centres has to become
 * two lines before it can be posted, and that is a property of the accounting
 * rather than of anything being wrong. Fix value replaces it only on a line
 * whose arithmetic the simulate pass rejected — a repair offered on a line
 * with nothing to repair is a control that does nothing when pressed.
 */
function LineActions({
  finding,
  onFix,
  onSplit,
}: {
  finding?: Finding;
  onFix: () => void;
  onSplit: () => void;
}) {
  if (finding && finding.fix !== undefined) {
    return (
      <Tooltip title={'Set the line total to ' + formatMoney(finding.fix)}>
        <Button
          variant="error"
          appearance="outline"
          size="sm"
          startIcon={<WrenchIcon size={14} />}
          onClick={onFix}
        >
          Fix value
        </Button>
      </Tooltip>
    );
  }

  return (
    <Tooltip title="Split this line">
      <IconButton
        variant="secondary"
        appearance="text"
        size="sm"
        aria-label="Split this line"
        onClick={onSplit}
      >
        <ScissorsIcon size={16} />
      </IconButton>
    </Tooltip>
  );
}

/**
 * The upload control: the button, and a caret for the other ways a document
 * can arrive.
 *
 * The frame draws these as one split control behind a dashed edge, the border
 * doing double duty as a drop target. Atoms has no dashed appearance and no
 * split button, and faking either means overriding Button's radius and
 * Divider's border style — so this is two stock controls side by side. A
 * dashed drop zone is a Button appearance to add, not a thing to hand-roll
 * per screen.
 */
function UploadFiles() {
  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

  return (
    <>
      <Stack direction="row" sx={{ gap: 0.5, alignItems: 'center' }}>
        <Button
          variant="secondary"
          appearance="outline"
          size="sm"
          startIcon={<UploadSimpleIcon />}
        >
          Upload Files
        </Button>
        <IconButton
          variant="secondary"
          appearance="text"
          size="sm"
          aria-label="Other ways to add a document"
          onClick={(event) => setAnchorEl(event.currentTarget)}
        >
          <CaretDownIcon />
        </IconButton>
      </Stack>
      <Menu
        anchorEl={anchorEl}
        open={anchorEl !== null}
        onClose={() => setAnchorEl(null)}
      >
        <MenuItem onClick={() => setAnchorEl(null)}>
          Upload from device
        </MenuItem>
        <MenuItem onClick={() => setAnchorEl(null)}>
          Attach from vendor portal
        </MenuItem>
      </Menu>
    </>
  );
}

/* ----------------------------------------------------------------- page */

export default function ErpPostingPage() {
  const [navOpen, setNavOpen] = React.useState(false);
  const [belowBar, setBelowBar] = React.useState<HTMLElement | null>(null);

  const [values, setValues] = React.useState<Record<string, string>>(() =>
    Object.fromEntries(HEADER_FIELDS.map((field) => [field.key, field.value]))
  );
  const [lines, setLines] = React.useState<readonly LineItem[]>(LINE_ITEMS);

  const [checking, setChecking] = React.useState(false);
  const [checked, setChecked] = React.useState(false);
  const [posting, setPosting] = React.useState(false);
  const [posted, setPosted] = React.useState(false);

  // One timer at a time: Simulate and Proceed cannot both be in flight,
  // because the second is disabled until the first has come back.
  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined
  );
  React.useEffect(() => () => clearTimeout(timer.current), []);

  /**
   * The findings are derived, not stored. Fixing a line has to clear the
   * finding that named it in the same render — a stored list goes stale the
   * moment the record changes under it, and a stale "line 3 is wrong" beside
   * a corrected line 3 is worse than no check at all.
   */
  const findings = checked ? simulate(lines) : [];
  const blocked = isBlocked(findings);
  const gap = variance(lines);

  const findingByLine = new Map<number, Finding>();
  for (const finding of findings) {
    if (finding.lineId !== undefined) {
      findingByLine.set(finding.lineId, finding);
    }
  }

  function runSimulate() {
    // Your accounting check, then the ERP's own dry run. Both answers come
    // back as one list of findings; severity is what decides whether the
    // post is blocked.
    setChecking(true);
    setPosted(false);
    timer.current = setTimeout(() => {
      setChecking(false);
      setChecked(true);
    }, SIMULATE_MS);
  }

  function runPost() {
    // Your ERP call. Nothing here can reach it until a simulate pass came
    // back clean, which is the point of the gate.
    setPosting(true);
    timer.current = setTimeout(() => {
      setPosting(false);
      setPosted(true);
    }, POST_MS);
  }

  function setLineCode(
    id: number,
    field: 'vatCode' | 'whtCode',
    code: string
  ) {
    setLines((previous) =>
      previous.map((line) =>
        line.id === id ? { ...line, [field]: code } : line
      )
    );
  }

  function applyToAll(field: 'vatCode' | 'whtCode', code: string) {
    setLines((previous) =>
      previous.map((line) => ({ ...line, [field]: code }))
    );
  }

  function fixLine(id: number) {
    setLines((previous) =>
      previous.map((line) =>
        line.id === id
          ? { ...line, lineTotal: money(line.quantity * line.unitPrice) }
          : line
      )
    );
  }

  const columns: GridColDef<LineItem>[] = [
    {
      field: 'id',
      headerName: '#',
      width: 56,
      sortable: false,
      filterable: false,
      renderCell: ({ row }) => <IndexCell value={row.id} />,
    },
    {
      field: 'description',
      headerName: 'Description',
      flex: 1.6,
      minWidth: 180,
    },
    {
      field: 'lineTotal',
      headerName: 'Line Total',
      width: 140,
      align: 'right',
      headerAlign: 'right',
      renderCell: ({ row }) => <AmountCell value={row.lineTotal} />,
    },
    {
      field: 'vatCode',
      headerName: 'VAT Tax Code',
      width: 200,
      sortable: false,
      filterable: false,
      renderHeader: () => (
        <TaxHeader
          label="VAT Tax Code"
          options={VAT_CODES}
          onApplyAll={(code) => applyToAll('vatCode', code)}
        />
      ),
      renderCell: ({ row }) => (
        <Select
          value={row.vatCode}
          onChange={(event) =>
            setLineCode(row.id, 'vatCode', event.target.value)
          }
          aria-label={'VAT tax code for line ' + row.id}
          fullWidth
        >
          {VAT_CODES.map((code) => (
            <MenuItem key={code.value} value={code.value}>
              {code.label}
            </MenuItem>
          ))}
        </Select>
      ),
    },
    {
      field: 'whtCode',
      headerName: 'WHT Tax Code',
      width: 200,
      sortable: false,
      filterable: false,
      renderHeader: () => (
        <TaxHeader
          label="WHT Tax Code"
          options={WHT_CODES}
          onApplyAll={(code) => applyToAll('whtCode', code)}
        />
      ),
      renderCell: ({ row }) => (
        <Select
          value={row.whtCode}
          onChange={(event) =>
            setLineCode(row.id, 'whtCode', event.target.value)
          }
          aria-label={'WHT tax code for line ' + row.id}
          fullWidth
        >
          {WHT_CODES.map((code) => (
            <MenuItem key={code.value} value={code.value}>
              {code.label}
            </MenuItem>
          ))}
        </Select>
      ),
    },
    {
      // No header. The column holds one control per row and the control says
      // what it does; a heading over it would name the column after whichever
      // of the two states happened to be more common.
      field: 'actions',
      headerName: '',
      width: 122,
      sortable: false,
      filterable: false,
      align: 'center',
      renderCell: ({ row }) => (
        <LineActions
          finding={findingByLine.get(row.id)}
          onFix={() => fixLine(row.id)}
          onSplit={() => {
            // Your split flow. One line becomes two, and both keep the
            // parent's tax codes until someone changes them.
          }}
        />
      ),
    },
  ];

  /* A page header, not an app bar: it spans the whole width and names the
     record, so the hamburger at its leading edge reads as "the navigation"
     rather than as the strip below it. */
  return (
    <Stack sx={{ height: '100vh', overflow: 'hidden' }}>
      <Navbar size="md">
        <IconButton
          variant="secondary"
          appearance="text"
          size="sm"
          aria-label="Open navigation"
          onClick={() => setNavOpen((previous) => !previous)}
        >
          <ListIcon />
        </IconButton>

        <NavbarTitle
          meta={[
            {
              icon: <TicketIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.ticket,
            },
            {
              // A building rather than a person: the meta line names the
              // vendor, and a vendor is a company.
              icon: <BuildingsIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.vendor,
            },
            {
              icon: <CalendarBlankIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.date,
            },
          ]}
          sx={{ ml: 3 }}
        >
          ERP Posting
        </NavbarTitle>

        <Box sx={{ flex: 1 }} />

        <Stack direction="row" sx={{ gap: ACTION_GAP, flexShrink: 0 }}>
          <Button variant="error" appearance="outline" size="sm">
            Reject
          </Button>
          <Button
            variant="secondary"
            appearance="outline"
            size="sm"
            loading={checking}
            onClick={runSimulate}
          >
            Simulate
          </Button>
          {/* Disabled until a clean pass. The label never changes and the
              button never moves — the only thing the check alters is whether
              it answers. */}
          <Tooltip
            title={
              posted
                ? 'Already posted'
                : !checked
                  ? 'Run Simulate first'
                  : blocked
                    ? 'Clear the errors below first'
                    : ''
            }
          >
            <Button
              size="sm"
              endIcon={<ArrowRightIcon size={NAVBAR_META_ICON_PX} />}
              disabled={!checked || blocked || posted}
              loading={posting}
              onClick={runPost}
            >
              Proceed
            </Button>
          </Tooltip>
        </Stack>
      </Navbar>

      {/* position: relative is what the overlay's absolute anchors to, so the
          main menu and its backdrop stop at the bar rather than running up
          over it. */}
      <Box
        ref={setBelowBar}
        sx={{
          flex: 1,
          minHeight: 0,
          display: 'flex',
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        {/* The workflow strip: sections of this record, not destinations in
            the app. No brand block and no user footer — the header above owns
            the top of the screen, and the account menu belongs to the main
            menu the hamburger brings back. */}
        <AppRail
          collapsed
          showBrand={false}
          showUser={false}
          nav={WORKFLOW_NAV}
          secondaryNav={WORKFLOW_SECONDARY_NAV}
        />

        <Stack sx={{ flex: 1, minWidth: 0, minHeight: 0 }}>
          {/* Findings sit above the form rather than beside the button that
              produced them: they are about the record, and the ones that name
              a line name one further down the page. */}
          {(findings.length > 0 || posted) && (
            <Stack sx={{ gap: 1, px: 3, pt: 2, flexShrink: 0 }}>
              {posted && (
                <Alert severity="success" floating>
                  Posted to the ERP as document 5100004821.
                </Alert>
              )}
              {/* No icon override. Alert draws one glyph for all four
                  severities on purpose — the resynced sheet puts the same
                  filled diamond in every state and changes only the colour —
                  so a per-severity glyph here would undo the component's own
                  decision. */}
              {findings.map((finding) => (
                <Alert
                  key={finding.id}
                  severity={finding.severity === 'error' ? 'error' : 'info'}
                  floating
                >
                  {finding.message}
                </Alert>
              ))}
            </Stack>
          )}

          <Box sx={{ px: 3, py: 2.5, flexShrink: 0 }}>
            {/* Eleven boxes, four across. Two kinds of field: the ones
                extraction and matching established, which are read-only here,
                and the ones the ERP needs that no earlier stage supplies. An
                editable amount would mean the invoice could change after it
                was matched; a locked posting field would mean the post could
                never be completed. */}
            <Grid container spacing={2.5}>
              {HEADER_FIELDS.map((field) => (
                <Grid key={field.key} size={{ xs: 12, sm: 6, lg: 3 }}>
                  <TextField
                    label={field.label}
                    required={field.required}
                    disabled={field.origin === 'carried'}
                    value={values[field.key] ?? ''}
                    placeholder={field.placeholder}
                    onChange={(event) =>
                      setValues((previous) => ({
                        ...previous,
                        [field.key]: event.target.value,
                      }))
                    }
                    fullWidth
                  />
                </Grid>
              ))}
              {/* Derived, so it is the one field with no entry in the record.
                  A variance you could type into would be a number you had
                  agreed with rather than one the accounting agreed with. */}
              <Grid size={{ xs: 12, sm: 6, lg: 3 }}>
                <TextField
                  label="Variance"
                  disabled
                  value={formatVariance(gap)}
                  fullWidth
                  status={checked && gap !== 0 ? 'error' : undefined}
                  helperText={
                    checked && gap !== 0
                      ? 'The lines do not add up to the invoice total'
                      : undefined
                  }
                />
              </Grid>
            </Grid>

            <Stack
              direction="row"
              sx={{ gap: 2, alignItems: 'flex-end', mt: 2 }}
            >
              <Stack sx={{ gap: 0.5 }}>
                {/* Inset to the same 8px a TextField label sits at, so this
                    block's label lines up with the ten above it. Position,
                    not restyling — the variant carries the type. */}
                <Typography
                  variant="caption"
                  sx={{ px: spacing.component.xs + 'px' }}
                >
                  Documents (1)
                </Typography>
                <UploadFiles />
              </Stack>
              <Chip
                size="sm"
                variant="secondary"
                icon={<FilePdfIcon />}
                label="Invoice-A.pdf"
              />
            </Stack>
          </Box>

          <Divider />

          {/* The grid is height: 100%, so it needs a parent with a definite
              height to be 100% of. minHeight: 0 is what makes flex: 1 mean
              "what is left" rather than "at least the rows", which would push
              the footer past the bottom edge. */}
          <Box sx={{ flex: 1, minHeight: 0 }}>
            <DataGrid
              size="sm"
              rows={lines as LineItem[]}
              columns={columns}
              rowNoun="line items"
              // The line the check rejected, tinted. The message above names
              // it; this is what makes "line 3" findable without counting.
              rowState={({ row }) =>
                findingByLine.has(row.id) ? 'error' : undefined
              }
              pageSizeOptions={PAGE_SIZE_OPTIONS}
              initialState={{
                pagination: { paginationModel: { pageSize: PAGE_SIZE } },
              }}
              disableColumnMenu
              disableRowSelectionOnClick
            />
          </Box>
        </Stack>

        {/* The main menu, floated back in over a record that stays put. The
            way out of the workflow to everything else. */}
        <AppRail
          overlay
          open={navOpen}
          onClose={() => setNavOpen(false)}
          onNavigate={() => setNavOpen(false)}
          defaultActive="dashboard"
          container={belowBar}
        />
      </Box>
    </Stack>
  );
}

'use client';

import * as React from 'react';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  DataGrid,
  Divider,
  Filter,
  IconButton,
  Link,
  Navbar,
  Stack,
  Tab,
  Tabs,
  TextField,
  Tooltip,
  Typography,
  countActiveFilters,
} from '@neofloai/atoms';
import {
  ArrowSquareOutIcon,
  FadersHorizontalIcon,
  HeadsetIcon,
  MagnifyingGlassIcon,
  PaperclipIcon,
  SidebarSimpleIcon,
  UploadSimpleIcon,
  WarningCircleIcon,
} from '@neofloai/atoms/icons';
import { fontFamilies, text, typography } from '@neofloai/atoms/tokens';

import type { FilterValue, GridColDef } from '@neofloai/atoms';

// The rail, the invoices and the facets are the application's. The rail is
// the same one every other screen in the workflow mounts, so it is imported
// rather than redrawn — a second copy would drift from the screens the
// Review button opens.
import { AppRail } from './AppRail';
import { INVOICE_FILTER_GROUPS, filterInvoices } from './invoices';

import type { Invoice, InvoiceStage } from './invoices';

/**
 * The stage an invoice is parked at, and the chip that says so.
 *
 * This map is the screen. Every other column tells you *which* invoice; the
 * stage tells you what the invoice is waiting for, and it is the only thing
 * on the row that decides where Review takes you — extraction review,
 * match review, or the posting screen.
 *
 * The four roles are the semantic ones every other status pill in the library
 * uses — `information`, `warning`, `success`, `error` — rather than the
 * hues in the frame. Read down the column it is a progression: the machine is
 * working, a human is needed, everything is validated, a stage has failed. A
 * decorative role like `purple` or `orange` carries no state, so a reader
 * could not tell from it which of two stages was the bad one.
 */
const STAGE_META: Record<
  InvoiceStage,
  {
    label: string;
    variant: 'information' | 'warning' | 'success' | 'error';
    Icon?: typeof WarningCircleIcon;
  }
> = {
  extraction: { label: 'Extraction', variant: 'information' },
  matching: { label: 'Matching', variant: 'warning' },
  posting: { label: 'ERP Posting', variant: 'success' },
  error: { label: 'Error', variant: 'error', Icon: WarningCircleIcon },
};

/**
 * Which invoices a tab is asking for. `open` is everything still moving
 * through the workflow, including the ones that have failed — an errored
 * invoice is the most open thing on the screen, not a closed one.
 */
const TABS = [
  { value: 'open', label: 'Open' },
  { value: 'closed', label: 'Closed' },
] as const;

/** Rows a page holds, and the choices the footer offers. */
const PAGE_SIZE = 10;
const PAGE_SIZE_OPTIONS = [10, 25, 50];

/* ---------------------------------------------------------------- cells */

/**
 * Two lines in one cell: the identifier over the thing that dates it.
 *
 * A grid cell centres a single line with `line-height`, so a stack of two
 * has to centre itself. Both lines ellipsise rather than wrap — a row is 56px
 * and a wrapped vendor name would push its neighbours out of alignment.
 */
function TwoLine({
  primary,
  secondary,
}: {
  primary: React.ReactNode;
  secondary: string;
}) {
  return (
    <Box
      component="span"
      sx={{
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        minWidth: 0,
        lineHeight: typography.body.b1.leading + 'px',
      }}
    >
      <Box
        component="span"
        sx={{ overflow: 'hidden', textOverflow: 'ellipsis' }}
      >
        {primary}
      </Box>
      <Box
        component="span"
        sx={(theme) => ({
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          fontSize: typography.body.b2.size,
          lineHeight: typography.body.b2.leading + 'px',
          color: text.default.caption.light,
          ...theme.applyStyles('dark', { color: text.default.caption.dark }),
        })}
      >
        {secondary}
      </Box>
    </Box>
  );
}

/**
 * The attachment, as the file it is. Placeholder ink rather than body,
 * because the filename is provenance — you read it to confirm the row is
 * about the document you meant, not to find out anything new.
 */
function AttachmentCell({ file }: { file: string }) {
  return (
    <Box
      component="span"
      sx={(theme) => ({
        display: 'flex',
        alignItems: 'center',
        gap: 0.5,
        minWidth: 0,
        lineHeight: 'normal',
        color: text.default.placeholder.light,
        ...theme.applyStyles('dark', { color: text.default.placeholder.dark }),
      })}
    >
      <PaperclipIcon size={14} style={{ flexShrink: 0 }} />
      <Box
        component="span"
        sx={{
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap',
        }}
      >
        {file}
      </Box>
    </Box>
  );
}

/**
 * Money, right-aligned, in the mono face.
 *
 * The digits are mono so the decimal points line up down the column — that
 * alignment is the only reason a reader can compare two amounts without
 * reading either of them. The currency mark stays in the sans caption
 * colour: it is the same on every row, so giving it the same weight as the
 * figure would make every row shout the same word.
 */
function AmountCell({ amount }: { amount: number }) {
  return (
    <Box
      component="span"
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'flex-end',
        gap: 0.25,
        width: '100%',
        lineHeight: 'normal',
      }}
    >
      <Box
        component="span"
        sx={(theme) => ({
          color: text.default.placeholder.light,
          ...theme.applyStyles('dark', {
            color: text.default.placeholder.dark,
          }),
        })}
      >
        $
      </Box>
      <Box
        component="span"
        sx={{ fontFamily: fontFamilies.product.mono }}
      >
        {amount.toLocaleString('en-US', { minimumFractionDigits: 2 })}
      </Box>
    </Box>
  );
}

/**
 * The one control on the row, plus the way out of the page.
 *
 * Three states, and they are not three styles of the same button. Review is
 * the primary route into the workflow and is drawn as an outline so it does
 * not compete with Upload Invoice up in the title band; View is the same
 * shape in the neutral role, for an invoice there is nothing to decide
 * about; Processing is the same shape again, disabled, because the row will
 * become one of the other two on its own and moving the control would make
 * the table jump under a reader's cursor.
 *
 * `Review` opens the invoice at whatever stage it is stuck at — the stage
 * is on the row, so the button does not need its own label per stage.
 */
function ActionCell({
  invoice,
  onOpen,
}: {
  invoice: Invoice;
  onOpen: (id: string, target: 'panel' | 'tab') => void;
}) {
  const busy = invoice.action === 'processing';

  return (
    <Stack direction="row" sx={{ gap: 1, alignItems: 'center' }}>
      <Button
        size="sm"
        appearance="outline"
        variant={invoice.action === 'review' ? 'primary' : 'secondary'}
        disabled={busy}
        startIcon={busy ? <CircularProgress size={14} color="inherit" /> : undefined}
        onClick={() => onOpen(invoice.id, 'panel')}
        sx={{ minWidth: 88 }}
      >
        {busy ? 'Processing' : invoice.action === 'review' ? 'Review' : 'View'}
      </Button>
      <Tooltip title="Open in new tab">
        <IconButton
          size="sm"
          variant="secondary"
          appearance="text"
          disabled={busy}
          aria-label={'Open invoice ' + invoice.reference + ' in a new tab'}
          onClick={() => onOpen(invoice.id, 'tab')}
        >
          <ArrowSquareOutIcon size={16} />
        </IconButton>
      </Tooltip>
    </Stack>
  );
}

/* -------------------------------------------------------------- columns */

/**
 * Six columns: who it came from, who it is from, where it is, what it is,
 * what it is worth, and the way in.
 *
 * The identity columns flex and the three on the right are fixed, so the
 * table absorbs the rail opening and closing by giving and taking from the
 * names — never from the amount or the button, whose widths are the two
 * things a reader scans down.
 */
function invoiceColumns(
  onOpen: (id: string, target: 'panel' | 'tab') => void
): GridColDef<Invoice>[] {
  return [
    {
      field: 'reference',
      headerName: 'Source ID/ Time',
      flex: 1.4,
      minWidth: 168,
      renderCell: ({ row }) => (
        <Box
          component="span"
          sx={{
            display: 'flex',
            alignItems: 'center',
            gap: 1,
            minWidth: 0,
            lineHeight: 'normal',
          }}
        >
          {/* The channel the invoice arrived on. A glyph rather than a
              column, because it is the same answer for most rows. */}
          <Tooltip title={row.channel}>
            <HeadsetIcon size={14} style={{ flexShrink: 0 }} />
          </Tooltip>
          <TwoLine
            primary={
              <Link
                href={'/invoices/' + row.id}
                color="primary"
                underline="hover"
              >
                {row.reference}
              </Link>
            }
            secondary={row.received}
          />
        </Box>
      ),
    },
    {
      field: 'vendor',
      headerName: 'Vendor / Invoice#',
      flex: 1.6,
      minWidth: 168,
      renderCell: ({ row }) => (
        <TwoLine primary={row.vendor} secondary={row.invoiceNumber} />
      ),
    },
    {
      field: 'stage',
      headerName: 'Status',
      width: 148,
      sortable: false,
      renderCell: ({ row }) => {
        const meta = STAGE_META[row.stage];
        return (
          <Chip
            size="sm"
            variant={meta.variant}
            label={meta.label}
            icon={meta.Icon ? <meta.Icon /> : undefined}
          />
        );
      },
    },
    {
      field: 'attachment',
      headerName: 'Invoice attachment',
      flex: 1.6,
      minWidth: 176,
      sortable: false,
      renderCell: ({ row }) => <AttachmentCell file={row.attachment} />,
    },
    {
      field: 'amount',
      headerName: 'Amount',
      width: 148,
      align: 'right',
      headerAlign: 'right',
      renderCell: ({ row }) => <AmountCell amount={row.amount} />,
    },
    {
      field: 'action',
      headerName: 'Action',
      width: 172,
      sortable: false,
      filterable: false,
      renderCell: ({ row }) => <ActionCell invoice={row} onOpen={onOpen} />,
    },
  ];
}

/* ----------------------------------------------------------------- page */

export default function InvoiceDashboardPage() {
  const [collapsed, setCollapsed] = React.useState(true);
  const [tab, setTab] = React.useState<'open' | 'closed'>('open');

  const [search, setSearch] = React.useState('');
  const [selection, setSelection] = React.useState<FilterValue>({});
  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

  const activeCount = countActiveFilters(INVOICE_FILTER_GROUPS, selection);
  const rows = filterInvoices(tab, search, selection);

  function handleOpen(id: string, target: 'panel' | 'tab') {
    const href = '/invoices/' + id;
    if (target === 'tab') {
      window.open(href, '_blank', 'noopener');
      return;
    }
    // Your router. The invoice opens at whatever stage it is parked at —
    // the screen decides that from the record, not from this call.
    window.location.assign(href);
  }

  const columns = React.useMemo(() => invoiceColumns(handleOpen), []);

  /* The rail runs the full height and the bar starts where it ends, so the
     outer box is a row: rail, then a column. */
  return (
    <Stack direction="row" sx={{ height: '100vh' }}>
      <AppRail collapsed={collapsed} active="dashboard" />

      <Stack sx={{ flex: 1, minWidth: 0 }}>
        <Navbar>
          <IconButton
            variant="secondary"
            appearance="text"
            size="sm"
            aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            onClick={() => setCollapsed((previous) => !previous)}
          >
            <SidebarSimpleIcon />
          </IconButton>
        </Navbar>

        {/* Four bands: title, tabs, toolbar, grid. Only the grid is
            elastic, so the footer lands on the bottom edge at any height. */}
        <Stack sx={{ flex: 1, minHeight: 0 }}>
          <Stack
            direction="row"
            sx={{
              px: 3,
              py: 3,
              gap: 2,
              alignItems: 'center',
              justifyContent: 'space-between',
            }}
          >
            <Typography variant="h3" component="h1">
              Invoice Dashboard
            </Typography>
            {/* The one thing on this screen that adds work to the queue,
                so it is the one filled button on it. */}
            <Button
              variant="primary"
              startIcon={<UploadSimpleIcon />}
              onClick={() => {
                /* your upload dialog */
              }}
            >
              Upload Invoice
            </Button>
          </Stack>

          {/* Tabs split the queue; they do not filter it. Open and Closed
              are different questions from the toolbar's, which is why they
              sit above the search box rather than inside the panel. */}
          <Tabs
            value={tab}
            onChange={(_, next) => setTab(next)}
            aria-label="Invoice queue"
            sx={{ px: 2 }}
          >
            {TABS.map((item) => (
              <Tab key={item.value} label={item.label} value={item.value} />
            ))}
          </Tabs>
          <Divider />

          <Stack
            direction="row"
            sx={{
              px: 3,
              py: 1.75,
              gap: 1.5,
              alignItems: 'center',
              justifyContent: 'space-between',
            }}
          >
            <TextField
              placeholder="Search..."
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              startAdornment={<MagnifyingGlassIcon />}
              sx={{ width: 280 }}
            />
            <Button
              variant="secondary"
              appearance="outline"
              size="sm"
              startIcon={<FadersHorizontalIcon />}
              onClick={(event) => setAnchorEl(event.currentTarget)}
            >
              Filter
              {activeCount > 0 && (
                <Chip
                  size="sm"
                  variant="primary"
                  component="span"
                  label={activeCount}
                />
              )}
            </Button>
          </Stack>
          <Divider />

          {/* A definite height for the grid to be 100% of. Without the
              minHeight the rows would push the column past the bottom of
              the screen instead of scrolling inside it. */}
          <Box sx={{ flex: 1, minHeight: 0 }}>
            <DataGrid
              size="sm"
              rows={rows}
              columns={columns}
              rowNoun="invoices"
              pageSizeOptions={PAGE_SIZE_OPTIONS}
              initialState={{
                pagination: { paginationModel: { pageSize: PAGE_SIZE } },
              }}
              disableRowSelectionOnClick
            />
          </Box>
        </Stack>
      </Stack>

      {/* The trigger sits at the right end of the toolbar, so the panel
          hangs off its right edge. */}
      <Filter
        groups={INVOICE_FILTER_GROUPS}
        value={selection}
        onChange={setSelection}
        anchorEl={anchorEl}
        open={anchorEl !== null}
        onClose={() => setAnchorEl(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      />
    </Stack>
  );
}
